package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen2Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_TooShort() {
        try {
            LocaleUtils.toLocale("a");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLowercase() {
        // First char not lowercase
        try {
            LocaleUtils.toLocale("En");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: En", e.getMessage());
        }

        // Second char not lowercase
        try {
            LocaleUtils.toLocale("eN");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: eN", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale result = LocaleUtils.toLocale("en");
        assertEquals(new Locale("en"), result);
    }

    @Test
    public void testToLocale_InvalidLengthAfterLanguage() {
        // Length 3 is invalid because if len > 2, it must be >= 5 (or handle special ch3 == '_')
        try {
            LocaleUtils.toLocale("ena");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: ena", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidSeparator() {
        // Length 5, but index 2 is not '_'
        try {
            LocaleUtils.toLocale("en-US");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-US", e.getMessage());
        }
    }

    @Test
    public void testToLocale_LanguageAndVariantWithUnderscoreAtCh3() {
        // This triggers: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Input example: "en__US" -> len=6, ch0='e', ch1='n', ch2='_', ch3='_'
        // Wait, the logic says: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Let's use "en__US"
        Locale result = LocaleUtils.toLocale("en__US");
        assertEquals(new Locale("en", "", "US"), result);
    }

    @Test
    public void testToLocale_InvalidCountryCase() {
        // ch3 or ch4 must be uppercase
        try {
            LocaleUtils.toLocale("en_us");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_us", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("en_uS");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_uS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageAndCountry() {
        Locale result = LocaleUtils.toLocale("en_US");
        assertEquals(new Locale("en", "US"), result);
    }

    @Test
    public void testToLocale_InvalidLengthForFullFormat() {
        // len 5 is handled above. If len is 6 and ch3/ch4 are upper, it hits len < 7 check
        // "en_US" is len 5.
        // To hit len < 7 check: we need len 6, ch2='_', ch3/ch4 upper, but len < 7.
        // Example: "en_USa" is len 6.
        try {
            LocaleUtils.toLocale("en_USa");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_USa", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidSeparatorForFullFormat() {
        // len 7, ch2='_', ch5 must be '_'
        try {
            LocaleUtils.toLocale("en_US-X");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US-X", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageCountryVariant() {
        Locale result = LocaleUtils.toLocale("en_US_FR");
        assertEquals(new Locale("en", "US", "FR"), result);
    }
}
